UPDATE co_aply_info
SET
     PRCS_STTS_CD = #{prcsSttsCd}
    ,RJCT_RSN =

            #{rjctRsn}
            NULL

    ,PRCS_DT = NOW()
    ,PRCS_USER_ID = #{adminId}
WHERE APLY_SN = #{aplySn}
  AND PRCS_STTS_CD = 'WAIT'

UPDATE co_info
SET USE_YN = #{useYn}
WHERE CO_ID = #{coId}

UPDATE user_info
SET USE_YN = #{useYn}
WHERE USER_ID = #{userId}

mapper.select:
SELECT SYS_LOG_SN ,LOG_SE_CD ,LOG_LEVEL_CD ,LOG_TITLE ,LOG_CN ,USER_ID ,REQUEST_URI ,CLIENT_IP_ADDR ,REG_DT FROM sys_log_info WHERE 1 = 1
AND LOG_LEVEL_CD = #{logLevelCd}
AND LOG_SE_CD = #{logSeCd}
AND ( LOG_TITLE LIKE CONCAT('%', #{searchValue}, '%') OR LOG_CN LIKE CONCAT('%', #{searchValue}, '%') OR USER_ID LIKE CONCAT('%', #{searchValue}, '%') OR CLIENT_IP_ADDR LIKE CONCAT('%', #{searchValue}, '%') )
ORDER BY REG_DT DESC LIMIT 500

